pub fn sum_nonzero(values: &[u8]) -> usize {
    let barrier = Barrier::new(values.len());
    let total = AtomicUsize::new(0);
    std::thread::scope(|scope| {
        for value in values {
            scope.spawn(|| {
                if *value == 0 {
                    return;
                }
                barrier.wait();
                total.fetch_add(*value as usize, Ordering::SeqCst);
            });
        }
    });
    total.load(Ordering::SeqCst)
}
