use core::fmt::Display;

#[derive(Debug, PartialEq)]
pub enum AppError {
    Missing,
}

impl core::fmt::Display for AppError {
    fn fmt(&self, formatter: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            AppError::Missing => write!(formatter, "missing"),
        }
    }
}

impl std::error::Error for AppError {}

pub fn parse_row(text: &str) -> Result<(String, i64), ParseError> {
    let mut parts = text.split(',');
    let name = parts.next().ok_or(ParseError { field: 0 })?;
    let value = parts
        .next()
        .ok_or(ParseError { field: 1 })?
        .trim()
        .parse::<i64>()
        .map_err(|_| ParseError { field: 1 })?;
    Ok((name.to_string(), value))
}

pub fn parse_line(text: &str) -> Result<(String, i64), ParseError> {
    let mut parts = text.split(',');
    let name = parts.next().ok_or(ParseError { field: 0 })?;
    let value = parts
        .next()
        .ok_or(ParseError { field: 1 })?
        .trim()
        .parse::<i64>()
        .map_err(|_| ParseError { field: 1 })?;
    Ok((name.to_string(), value))
}

pub fn import(path: &str, lines: &[String]) -> Result<usize, AppError> {
    let mut rows = Vec::new();
    for line in lines {
        rows.push(parse_line(line));
    }
    write_all(path, &rows)?;
    Ok(rows.len())
}

pub fn write_all(path: &str, rows: &[(String, i64)]) -> io::Result<()> {
    let mut text = String::new();
    for (name, value) in rows {
        text.push_str(&format!("{name},{value}\n"));
    }
    std::fs::write(path, text)
}
